/**
 * Stage 4, Step 6: build the corrected CSV and verify it.
 *
 * - Written from the edited view (the original file is never touched), as
 *   UTF-8 with a byte-order mark (Stage 4 decision 3), with the original
 *   separator. Stage 5 (CSV Validator, decision 3): the separator, line endings
 *   and “UTF-8 without BOM” can be chosen; values are written exactly either way.
 * - Built in chunks: each ~2 MB of text becomes a small Blob part straight away,
 *   so a 150 MB file never exists as one giant string in memory.
 * - Verification (owner-approved Option A, V1/V2): the generated bytes are read
 *   back with DataFixer's own CSV reader in streaming mode and compared cell by
 *   cell with the expected data. The result is only offered if every cell matches.
 */
import { EngineError } from "../errors.ts";
import { throwIfCancelled, yieldToEventLoop, type CancelToken } from "../cancel.ts";
import type { SheetModel } from "../types.ts";
import { parseCsv } from "../csv/parse-csv.ts";

export interface CsvWriteOptions {
  delimiter: string;
  lineEnding: "\n" | "\r\n";
  /** Start the file with the UTF-8 byte-order mark (default true: Excel then reads it as UTF-8). */
  bom?: boolean;
  /** Excel source: write values as shown (formatted dates and numbers). CSV source: raw text. */
  useDisplay: boolean;
  /**
   * Stage 6 (Excel to CSV, decision 4): “plain values” instead of values as shown:
   * dates as yyyy-mm-dd (with hh:mm:ss when there is a time), numbers in full
   * precision without formatting, TRUE/FALSE. Overrides useDisplay.
   */
  plain?: boolean;
  cancel?: CancelToken;
  onProgress?: (done: number, total: number) => void;
  /** Characters of text per Blob part (default ~2M). */
  chunkChars?: number;
}

const BOM = new Uint8Array([0xef, 0xbb, 0xbf]);
const ROWS_PER_YIELD = 20_000;

const pad = (n: number) => String(n).padStart(2, "0");

/**
 * An Excel date serial as yyyy-mm-dd (and hh:mm:ss when there is a time;
 * a time without a date as hh:mm:ss). 1900 system: serial 60 is Excel's
 * non-existent 29 February 1900, shown as Excel shows it.
 */
export function serialToIso(v: number, date1904 = false): string {
  if (!Number.isFinite(v) || v < 0) return String(v);
  let days = Math.floor(v);
  let secs = Math.round((v - days) * 86_400);
  if (secs === 86_400) {
    days++;
    secs = 0;
  }
  const time = secs ? `${pad(Math.floor(secs / 3600))}:${pad(Math.floor((secs % 3600) / 60))}:${pad(secs % 60)}` : "";
  if (!date1904 && days === 0) return time || "00:00:00";
  let date: string;
  if (!date1904 && days === 60) date = "1900-02-29";
  else {
    const base = date1904 ? Date.UTC(1904, 0, 1) : days < 60 ? Date.UTC(1899, 11, 31) : Date.UTC(1899, 11, 30);
    const d = new Date(base + days * 86_400_000);
    date = `${String(d.getUTCFullYear()).padStart(4, "0")}-${pad(d.getUTCMonth() + 1)}-${pad(d.getUTCDate())}`;
  }
  return time ? `${date} ${time}` : date;
}

/** The text a cell is written as. */
export function cellOutText(sheet: SheetModel, r: number, c: number, useDisplay: boolean, plain = false): string {
  const g = sheet.grid;
  const v = g.get(r, c);
  if (v === null) return "";
  if (plain) {
    if (typeof v === "boolean") return v ? "TRUE" : "FALSE";
    if (typeof v === "number") return g.isDate?.(r, c) ? serialToIso(v, sheet.date1904 ?? false) : String(v);
    return String(v);
  }
  if (useDisplay && g.display) return g.display(r, c);
  if (typeof v === "boolean") return v ? "TRUE" : "FALSE";
  return String(v);
}

/** RFC 4180 quoting: quote a field containing the separator, a quote or a line break. */
export function quoteField(s: string, delimiter: string): string {
  if (s.includes('"')) return `"${s.replace(/"/g, '""')}"`;
  if (s.includes(delimiter) || s.includes("\n") || s.includes("\r")) return `"${s}"`;
  return s;
}

/** One row as written (cells, in order). Rows keep their own length (ragged rows stay ragged). */
export function expectedRow(sheet: SheetModel, r: number, useDisplay: boolean, plain = false): string[] {
  const len = sheet.grid.rowLength(r);
  const out = new Array<string>(len);
  for (let c = 0; c < len; c++) out[c] = cellOutText(sheet, r, c, useDisplay, plain);
  return out;
}

export async function buildCsv(sheet: SheetModel, o: CsvWriteOptions): Promise<{ blob: Blob; formulaLike: number }> {
  const rows = sheet.grid.rowCount;
  const chunkChars = o.chunkChars ?? 2_000_000;
  const parts: BlobPart[] = o.bom === false ? [] : [BOM];
  let buf: string[] = [];
  let bufChars = 0;
  let formulaLike = 0;
  for (let r = 0; r < rows; r++) {
    const cells = expectedRow(sheet, r, o.useDisplay, o.plain);
    for (let c = 0; c < cells.length; c++) {
      const s = cells[c]!;
      const ch = s.charCodeAt(0);
      if (ch === 0x3d || ch === 0x2b || ch === 0x2d || ch === 0x40) if (!/^[+-]\d+(\.\d+)?([eE][+-]?\d+)?$/.test(s)) formulaLike++;
      cells[c] = quoteField(s, o.delimiter);
    }
    const line = cells.join(o.delimiter) + o.lineEnding;
    buf.push(line);
    bufChars += line.length;
    if (bufChars >= chunkChars) {
      parts.push(new Blob([buf.join("")]));
      buf = [];
      bufChars = 0;
    }
    if (r % ROWS_PER_YIELD === ROWS_PER_YIELD - 1) {
      throwIfCancelled(o.cancel);
      o.onProgress?.(r + 1, rows);
      await yieldToEventLoop();
    }
  }
  if (buf.length) parts.push(new Blob([buf.join("")]));
  o.onProgress?.(rows, rows);
  return { blob: new Blob(parts, { type: "text/csv;charset=utf-8" }), formulaLike };
}

export interface CsvVerification {
  rows: number;
  cells: number;
}

/**
 * Read the generated bytes back with DataFixer's CSV reader (streaming) and
 * compare every cell with the expected data. Throws a clear error on any
 * difference; nothing is offered for download in that case.
 */
export async function verifyCsv(
  blob: Blob,
  sheet: SheetModel,
  o: Pick<CsvWriteOptions, "delimiter" | "useDisplay" | "cancel" | "bom" | "plain"> & { onProgress?: (loaded: number, total: number) => void },
): Promise<CsvVerification> {
  const head = new Uint8Array(await blob.slice(0, 3).arrayBuffer());
  const hasBom = head[0] === 0xef && head[1] === 0xbb && head[2] === 0xbf;
  if (o.bom !== false && !hasBom) throw verificationFailed("the file doesn't start with the UTF-8 byte-order mark");
  // Without a BOM, a first value that itself starts with U+FEFF would look like one and be lost when read.
  if (o.bom === false && hasBom) throw verificationFailed("the first value starts with an invisible byte-order mark, which programs would remove");
  const expectedRows = sheet.grid.rowCount;
  let seen = 0;
  let cells = 0;
  let trailingEmpty = 0;
  const same = (got: string[], want: string[]) => {
    // An empty line reads back as one empty cell.
    if (want.length === 0) return got.length === 1 && got[0] === "";
    if (got.length !== want.length) return false;
    for (let c = 0; c < want.length; c++) if (got[c] !== want[c]) return false;
    return true;
  };
  await parseCsv(blob, "verify", {
    delimiter: o.delimiter,
    // Always read as UTF-8 (what was written), whatever the start of the file looks like.
    encoding: "utf-8",
    cancel: o.cancel,
    onProgress: o.onProgress,
    rowSink: (rows, first) => {
      for (let k = 0; k < rows.length; k++) {
        const r = first + k;
        const got = rows[k]!;
        if (r >= expectedRows) {
          // The final line break produces one empty row; anything else is extra data.
          if (got.length === 1 && got[0] === "" && trailingEmpty === 0) {
            trailingEmpty++;
            continue;
          }
          throw verificationFailed(`row ${r + 1} shouldn't exist`);
        }
        const want = expectedRow(sheet, r, o.useDisplay, o.plain);
        if (!same(got, want)) {
          const c = want.findIndex((w, i) => got[i] !== w);
          throw verificationFailed(`row ${r + 1}${c >= 0 ? `, column ${c + 1}` : ""} doesn't match`);
        }
        cells += want.length;
        seen++;
      }
    },
  });
  if (seen !== expectedRows) throw verificationFailed(`${seen} rows were read back instead of ${expectedRows}`);
  return { rows: seen, cells };
}

function verificationFailed(detail: string): EngineError {
  return new EngineError(
    "internal",
    "The corrected file didn't pass DataFixer's check, so it was not offered for download. Your changes are kept. Please try again; if it keeps happening, the file may contain content DataFixer can't write correctly yet.",
    `CSV verification failed: ${detail}`,
  );
}
